package cn.iocoder.yudao.module.zsjos.controller.admin.review; import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.zsjos.controller.admin.review.vo.*; import cn.iocoder.yudao.module.zsjos.service.review.ReviewReportService; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List; import static cn.iocoder.yudao.framework.common.pojo.CommonResult.success; import static cn.iocoder.yudao.framework.security.core.util.SecurityFrameworkUtils.getLoginUserId; @RestController @RequestMapping("/zsjos/reviews") public class ReviewReportController { @Resource private ReviewReportService service; @GetMapping("/list") @PreAuthorize("@ss.hasPermission('zsjos:review:query')") public CommonResult<List<ReviewReportRespVO>> list(){return success(service.list(getLoginUserId()));} @PostMapping("/create") @PreAuthorize("@ss.hasPermission('zsjos:review:create')") public CommonResult<Long> create(@Valid @RequestBody ReviewReportSaveReqVO req){return success(service.create(req,getLoginUserId()));} @PostMapping("/{id}/submit") @PreAuthorize("@ss.hasPermission('zsjos:review:submit')") public CommonResult<Boolean> submit(@PathVariable Long id,@RequestParam Integer version){service.submit(id,version,getLoginUserId());return success(true);} @PostMapping("/{id}/approve") @PreAuthorize("@ss.hasPermission('zsjos:review:approve')") public CommonResult<Boolean> approve(@PathVariable Long id,@RequestParam Integer version){service.approve(id,version,getLoginUserId());return success(true);} @PostMapping("/{id}/reject") @PreAuthorize("@ss.hasPermission('zsjos:review:approve')") public CommonResult<Boolean> reject(@PathVariable Long id,@RequestParam Integer version,@RequestParam String reason){service.reject(id,version,reason,getLoginUserId());return success(true);} @PostMapping("/{id}/archive") @PreAuthorize("@ss.hasPermission('zsjos:review:archive')") public CommonResult<Boolean> archive(@PathVariable Long id,@RequestParam Integer version){service.archive(id,version,getLoginUserId());return success(true);} }
